CREATE DATABASE IF NOT EXISTS if0_43039135_school_management CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE if0_43039135_school_management;

CREATE TABLE admins (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, display_name VARCHAR(150) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE classes (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, legacy_id VARCHAR(80) NULL UNIQUE, name VARCHAR(100) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sections (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, legacy_id VARCHAR(100) NULL UNIQUE, class_legacy_id VARCHAR(80) NULL, class_id INT UNSIGNED NULL, name VARCHAR(100) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_sections_class FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE SET NULL);
CREATE TABLE students (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, legacy_id VARCHAR(100) NULL UNIQUE, admission_no VARCHAR(100) NULL, roll_no VARCHAR(50) NULL, name VARCHAR(180) NOT NULL, father_name VARCHAR(180) NULL, date_of_birth DATE NULL, phone VARCHAR(50) NULL, address VARCHAR(255) NULL, section_legacy_id VARCHAR(100) NULL, section_id INT UNSIGNED NULL, status ENUM('active','inactive','left') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_student_name(name), INDEX idx_roll(roll_no), CONSTRAINT fk_students_section FOREIGN KEY(section_id) REFERENCES sections(id) ON DELETE SET NULL);
CREATE TABLE teachers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(180) NOT NULL, designation VARCHAR(120) NULL, qualification VARCHAR(180) NULL, phone VARCHAR(50) NULL, email VARCHAR(150) NULL, address VARCHAR(255) NULL, status ENUM('active','inactive') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_teacher_name(name));
CREATE TABLE subjects (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, class_id INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_subject_class FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE SET NULL);
CREATE TABLE exams (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, academic_year VARCHAR(30) NOT NULL, is_published TINYINT(1) NOT NULL DEFAULT 0, is_demo TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE results (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, student_id INT UNSIGNED NOT NULL, exam_id INT UNSIGNED NOT NULL, total_marks DECIMAL(10,2) NOT NULL DEFAULT 0, obtained_marks DECIMAL(10,2) NOT NULL DEFAULT 0, percentage DECIMAL(6,2) NOT NULL DEFAULT 0, grade VARCHAR(20) NULL, is_demo TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_student_exam(student_id,exam_id), CONSTRAINT fk_result_student FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE, CONSTRAINT fk_result_exam FOREIGN KEY(exam_id) REFERENCES exams(id) ON DELETE CASCADE);
CREATE TABLE result_subjects (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, result_id INT UNSIGNED NOT NULL, subject_id INT UNSIGNED NOT NULL, total_marks DECIMAL(10,2) NOT NULL DEFAULT 0, obtained_marks DECIMAL(10,2) NOT NULL DEFAULT 0, UNIQUE KEY uq_result_subject(result_id,subject_id), CONSTRAINT fk_rs_result FOREIGN KEY(result_id) REFERENCES results(id) ON DELETE CASCADE, CONSTRAINT fk_rs_subject FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE RESTRICT);
CREATE TABLE school_content (content_key VARCHAR(100) PRIMARY KEY, content_value TEXT NULL);
CREATE TABLE school_stories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, story_text TEXT NOT NULL, sort_order INT NOT NULL DEFAULT 0);
